package nl.smartstreamlabs.sbwdroneconfig;
import net.minecraft.client.gui.*;import net.minecraft.client.gui.components.*;import net.minecraft.client.gui.screens.inventory.AbstractContainerScreen;import net.minecraft.world.entity.player.Inventory;import net.minecraft.network.chat.Component;
/** Existing mission request and vanilla menu buttons; no second command protocol. */
public class Fl01Screen extends AbstractContainerScreen<Fl01Menu>{
 private EditBox x,y,z,cruise;private Button launch,unload,paint,load,droneInventory;private boolean dirty;
 public Fl01Screen(Fl01Menu m,Inventory i,Component title){super(m,i,title);imageWidth=300;imageHeight=238;inventoryLabelY=-10000;}
 private EditBox field(int dx,int dy,int width){var b=new EditBox(font,leftPos+dx,topPos+dy,width,18,Component.literal("Coordinate"));b.setMaxLength(32);return addRenderableWidget(b);}
 private Button button(String text,int dx,int dy,int w,int action){return addRenderableWidget(Button.builder(Component.literal(text),b->{if(action==10&&dirty)saveDraft();if(minecraft.gameMode!=null)minecraft.gameMode.handleInventoryButtonClick(menu.containerId,action);}).bounds(leftPos+dx,topPos+dy,w,18).build());}
 private void saveDraft(){AddonNetwork.CHANNEL.sendToServer(new MissionRequest(menu.containerId,menu.missionPos(),true,false,x.getValue(),y.getValue(),z.getValue(),cruise.getValue()));dirty=false;}
 @Override protected void init(){super.init();x=field(12,112,88);y=field(106,112,88);z=field(200,112,88);cruise=field(12,149,112);var p=menu.missionPlatform(minecraft.player);if(p!=null){var d=p.mission();x.setValue(d.x);y.setValue(d.y);z.setValue(d.z);cruise.setValue(d.cruise);}for(var b:new EditBox[]{x,y,z,cruise})b.setResponder(v->dirty=true);
  addRenderableWidget(Button.builder(Component.literal("Apply coordinates"),b->{AddonNetwork.CHANNEL.sendToServer(new MissionRequest(menu.containerId,menu.missionPos(),true,false,x.getValue(),y.getValue(),z.getValue(),cruise.getValue()));dirty=false;}).bounds(leftPos+136,topPos+149,152,18).build());load=button("Load",12,185,50,3);unload=button("Unload",66,185,50,1);paint=button("Variant",120,185,60,4);launch=button("LAUNCH",12,210,182,0);button("Cancel",200,210,88,2);droneInventory=button("Drone Inventory",184,185,104,10);
 }
 @Override public void containerTick(){super.containerTick();droneInventory.active=menu.inventoryAvailable();droneInventory.setTooltip(Tooltip.create(Component.literal(menu.inventoryHint())));launch.active=menu.reason()==0&&!dirty;unload.active=paint.active=menu.phase()==2;load.active=menu.phase()==0;}
 @Override protected void renderBg(GuiGraphics g,float p,int mx,int my){g.fill(leftPos,topPos,leftPos+imageWidth,topPos+imageHeight,0xf0101c24);g.fill(leftPos,topPos,leftPos+imageWidth,topPos+3,0xff9eb46f);g.fill(leftPos+20,topPos+43,leftPos+40,topPos+63,0xff39434a);}
 @Override protected void renderLabels(GuiGraphics g,int mx,int my){g.drawString(font,"FL-LP • Flamingo Launch Platform",12,12,0xe5e8da,false);var item=menu.getSlot(0).getItem();g.drawString(font,item.isEmpty()?"No FL-01 loaded":Fl01Item.data(item).getBoolean("Pink")?"FL-01 • Pink nose":"FL-01 • Dark nose",48,47,0xffffff,false);g.drawString(font,"Fuel: "+menu.fuel()+" ticks",48,61,0xb8cad2,false);g.drawString(font,Component.translatable(Fl01PlatformBlockEntity.reasonKey(menu.reason())),12,80,menu.reason()==0?0xa3df9f:0xe6ba79,false);g.drawString(font,"Monitor + C: launch and pilot manually",12,27,0xa9c7d5,false);g.drawString(font,"X",12,101,0xffffff,false);g.drawString(font,"Y",106,101,0xffffff,false);g.drawString(font,"Z",200,101,0xffffff,false);g.drawString(font,"Cruise Y (optional)",12,138,0xc7d4d7,false);var p=menu.missionPlatform(minecraft.player);if(p!=null){var d=p.mission();String text=!d.message.isEmpty()?d.message:d.valid?String.format(java.util.Locale.ROOT,"Distance: %.1f blocks | Last: %s",p.missionMount().distanceTo(d.target),d.status):"Enter and apply a destination";g.drawString(font,font.plainSubstrByWidth(text,276),12,171,0xd9c482,false);}}
 @Override public void render(GuiGraphics g,int mx,int my,float p){renderBackground(g);super.render(g,mx,my,p);renderTooltip(g,mx,my);}
}
